const S={corpus:[],index:null,vectors:null,ready:false};
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
function toks(text){let out=[],s=text.toLowerCase();for(const run of s.match(/[\u4e00-\u9fff]+/g)||[]){out.push(...run);for(const n of [2,3,4])for(let i=0;i<=run.length-n;i++)out.push(run.slice(i,i+n))}out.push(...(s.match(/[a-z0-9][a-z0-9._%+-]*/g)||[]));return out}
function fnv(s){let h=2166136261;for(const b of new TextEncoder().encode(s)){h^=b;h=Math.imul(h,16777619)>>>0}return h}
function page(d){return d.page_start===d.page_end?'第'+d.page_start+'页':'第'+d.page_start+'–'+d.page_end+'页'}
function section(d){return d.section||d.chapter||'未标章节'}
async function load(){try{const [c,i,v]=await Promise.all([fetch('data/corpus.json').then(r=>r.json()),fetch('data/index.json').then(r=>r.json()),fetch('data/vectors.bin').then(r=>r.arrayBuffer())]);S.corpus=c;S.index=i;S.vectors=new Int8Array(v);S.ready=true;$('#status').textContent='● 索引就绪 · '+i.count.toLocaleString()+' 切块';$('#status').classList.add('ready');const sel=$('#company');for(const x of i.companies)sel.insertAdjacentHTML('beforeend','<option>'+esc(x)+'</option>');$('#textCount').textContent=c.filter(x=>x.content_type==='text').length.toLocaleString();$('#tableCount').textContent=c.filter(x=>x.content_type==='table').length.toLocaleString()}catch(e){$('#status').textContent='索引加载失败，请刷新重试';console.error(e)}}
function search(q){const start=performance.now(),qt=toks(q),qc=new Map();for(const t of qt)qc.set(t,(qc.get(t)||0)+1);const bm=new Float64Array(S.index.count),qv=new Float64Array(S.index.dim);for(const [t,qn] of qc){const p=S.index.postings[t];if(!p)continue;const df=p.length/2,idf=Math.log(1+(S.index.count-df+.5)/(df+.5));for(let j=0;j<p.length;j+=2){const id=p[j],tf=p[j+1],dl=S.index.lengths[id];bm[id]+=idf*(tf*2.35)/(tf+1.35*(.28+.72*dl/S.index.avgdl))}const w=(1+Math.log(qn))*(Math.log((S.index.count+1)/(df+1))+1),h=fnv(t);qv[h%S.index.dim]+=((h>>>30)&1)===0?w:-w}let norm=Math.hypot(...qv)||1;for(let i=0;i<qv.length;i++)qv[i]/=norm;let maxbm=Math.max(...bm)||1,rows=[];const company=$('#company').value,allowText=$('#textType').checked,allowTable=$('#tableType').checked;for(let id=0;id<S.corpus.length;id++){const d=S.corpus[id];if(company&&d.company!==company)continue;if(d.content_type==='text'&&!allowText||d.content_type==='table'&&!allowTable)continue;let cos=0,off=id*S.index.dim;for(let k=0;k<S.index.dim;k++)cos+=qv[k]*(S.vectors[off+k]/127);const score=.53*Math.max(0,cos)+.47*(bm[id]/maxbm);if(score>0)rows.push({id,d,score,bm:bm[id],cos})}rows.sort((a,b)=>b.score-a.score);return {rows:rows.slice(0,12),ms:Math.round(performance.now()-start)}}
function bestSentences(rows,q){const keys=[...new Set(toks(q).filter(x=>x.length>=2))],cand=[];for(let rank=0;rank<Math.min(7,rows.length);rank++){const r=rows[rank];for(let s of r.d.text.split(/[。！？\n]+/)){s=s.trim();if(s.length<18||s.length>260)continue;const hit=keys.filter(k=>s.toLowerCase().includes(k)).length;cand.push({s,r,v:r.score+hit*.08-rank*.012})}}cand.sort((a,b)=>b.v-a.v);const out=[];for(const x of cand){if(out.some(y=>y.r.id===x.r.id||y.s.includes(x.s.slice(0,18))))continue;out.push(x);if(out.length===3)break}if(!out.length&&rows[0])out.push({s:rows[0].d.text.slice(0,240),r:rows[0]});return out}
function card(r,n){const d=r.d,txt=d.text.replace(/\s+/g,' ').slice(0,280);return '<article class=\'source\' id=\'source-'+n+'\'><span class=\'n\'>['+n+']</span><h3>'+esc(d.company)+' · '+esc(d.content_type==='table'?'表格':'正文')+'</h3><div class=\'meta\'>'+esc(section(d))+' · '+page(d)+'</div><p>'+esc(txt)+'</p></article>'}
function render(q,res){$('#empty').classList.add('hidden');$('#results').classList.remove('hidden');$('#latency').textContent='本地检索 '+res.ms+' ms';if(!res.rows.length){$('#answerText').innerHTML='<p>当前筛选范围内没有找到足够相关的原文。请调整公司或内容类型后重试。</p>';$('#sources').innerHTML='';$('#sourceCount').textContent='0 条来源';return}const chosen=bestSentences(res.rows,q),refs=[];for(const x of chosen)if(!refs.some(r=>r.id===x.r.id))refs.push(x.r);for(const r of res.rows)if(refs.length<4&&!refs.some(x=>x.id===r.id))refs.push(r);const refno=r=>refs.findIndex(x=>x.id===r.id)+1;$('#answerText').innerHTML=chosen.map(x=>'<p>'+esc(x.s)+'。 <button class=\'ref\' data-ref=\''+refno(x.r)+'\'>['+refno(x.r)+']</button></p>').join('');$('#sources').innerHTML=refs.slice(0,4).map((r,i)=>card(r,i+1)).join('');$('#sourceCount').textContent=refs.length+' 条核心来源';const more=res.rows.filter(r=>!refs.some(x=>x.id===r.id)).slice(0,5);$('#more').innerHTML=more.map((r,i)=>card(r,i+5)).join('');document.querySelectorAll('.ref').forEach(b=>b.onclick=()=>{const el=$('#source-'+b.dataset.ref);el.scrollIntoView({behavior:'smooth',block:'center'});el.classList.add('flash');setTimeout(()=>el.classList.remove('flash'),1300)});$('#results').scrollIntoView({behavior:'smooth',block:'start'})}
$('#form').addEventListener('submit',e=>{e.preventDefault();const q=$('#query').value.trim();if(!q)return $('#query').focus();if(!S.ready)return alert('索引仍在加载，请稍候');const b=$('#ask');b.disabled=true;b.firstChild.textContent='检索中 ';requestAnimationFrame(()=>{try{render(q,search(q))}finally{b.disabled=false;b.firstChild.textContent='检索并回答 '}})});
$('#examples').addEventListener('click',e=>{if(e.target.tagName!=='BUTTON')return;$('#query').value=e.target.textContent;$('#form').requestSubmit()});
$('#reset').onclick=()=>{$('#company').value='';$('#textType').checked=$('#tableType').checked=true};
const dialog=$('#method');$('#methodBtn').onclick=()=>dialog.showModal();dialog.querySelector('.close').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close()};
$('#query').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')$('#form').requestSubmit()});
async function registerWebMCP(){const ctx=document.modelContext;if(!ctx?.registerTool)return;try{await ctx.registerTool({name:'search_ai_reports',title:'检索中国 AI 公司半年报',description:'用向量与 BM25 混合检索 12 家中国 AI 公司的 2026 年半年报，并在页面显示带公司、章节和页码出处的答案。',inputSchema:{type:'object',properties:{question:{type:'string',minLength:2}},required:['question'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input.question!=='string'||input.question.trim().length<2)throw new Error('question 至少需要 2 个字符');const q=input.question.trim();$('#query').value=q;const res=search(q);render(q,res);return {question:q,matches:res.rows.length,sources:res.rows.slice(0,4).map(x=>({company:x.d.company,section:section(x.d),page:page(x.d)}))}}})}catch(e){console.warn('WebMCP registration failed',e)}}
const rawSearch=search;search=function(q){const res=rawSearch(q),named=S.index.companies.filter(x=>q.includes(x.replace(/股份有限公司|有限公司/g,''))||q.includes(x));for(const r of res.rows){if(named.length)r.score*=named.includes(r.d.company)?1.35:.55;if(/营业收入|净利润|总资产|现金流/.test(q)){if(/主要会计数据和财务指标|利润表/.test(section(r.d)))r.score+=.18;if(/\|\s*(营业收入|营业总收入|净利润|总资产)/.test(r.d.text))r.score+=.22}}res.rows.sort((a,b)=>b.score-a.score);return res};
bestSentences=function(rows,q){const keys=[...new Set(toks(q).filter(x=>x.length>=2))],cand=[];for(let rank=0;rank<rows.length;rank++){const r=rows[rank];for(let s of r.d.text.split(/[。！？\n]+/)){s=s.trim();if(s.length<18||s.length>280||/^\|?\s*---/.test(s))continue;const hit=keys.filter(k=>s.includes(k)).length,num=/\d[\d,.]*%?/.test(s)?1:0,header=/公司名称|公司类型|项目\s*\|/.test(s)?1:0;cand.push({s,r,v:r.score+hit*.08+num*.22-header*.35-rank*.008})}}cand.sort((a,b)=>b.v-a.v);const out=[];for(const x of cand){if(out.some(y=>y.r.id===x.r.id))continue;out.push(x);if(out.length===3)break}return out.length?out:[{s:rows[0].d.text.slice(0,240),r:rows[0]}]};
load().then(()=>{registerWebMCP();const q=new URLSearchParams(location.search).get('q');if(q){$('#query').value=q;$('#form').requestSubmit()}});
